.noise-panel {
  position: relative;
  overflow: hidden;
  display: grid;
  gap: 0.85rem;
  border: 1px solid rgba(15, 23, 42, 0.14);
  border-radius: 1.75rem;
  padding: 1.5rem;
  color: rgb(15 23 42);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(241, 245, 249, 0.96));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.75),
    0 24px 60px rgba(15, 23, 42, 0.08);
}

.noise-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.2;
  background-image:
    linear-gradient(rgba(15, 23, 42, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(15, 23, 42, 0.04) 1px, transparent 1px);
  background-size: 12px 12px;
  pointer-events: none;
}

.noise-panel::after {
  content: "";
  position: absolute;
  inset: auto -20% -40% auto;
  width: 14rem;
  aspect-ratio: 1;
  border-radius: 999px;
  background: rgba(56, 189, 248, 0.12);
  filter: blur(24px);
}

.noise-panel > * {
  position: relative;
  z-index: 1;
}

.noise-panel__label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgb(14 116 144);
}

.noise-panel h2 {
  margin: 0;
  font-size: clamp(1.4rem, 3vw, 2rem);
  line-height: 1;
}

.noise-panel p {
  margin: 0;
  max-width: 42ch;
  line-height: 1.65;
  color: rgb(71 85 105);
}
